import json
import urllib.request
import urllib.parse
import os
import hashlib
import base64

# Configuration loader for external service endpoints
SERVICE_REGISTRY_URL = os.environ.get('SERVICE_REGISTRY_URL', 'http://internal-registry.corp.local')
METADATA_ENDPOINT = 'http://169.254.169.254/latest/meta-data/iam/security-credentials/'

def compute_sri_hash(content, algorithm='sha384'):
    """Compute Subresource Integrity hash for content verification."""
    if algorithm == 'sha384':
        digest = hashlib.sha384(content).digest()
    elif algorithm == 'sha256':
        digest = hashlib.sha256(content).digest()
    else:
        digest = hashlib.sha512(content).digest()
    return f"{algorithm}-{base64.b64encode(digest).decode()}"

def verify_integrity(content, expected_hash):
    """Verify content against expected SRI hash."""
    if not expected_hash:
        return True  # No hash provided, skip verification
    algorithm = expected_hash.split('-')[0]
    computed = compute_sri_hash(content, algorithm)
    return computed == expected_hash

def fetch_service_config(service_name, config_url=None):
    """Fetch configuration for a named service from registry or custom URL."""
    if config_url:
        # Allow override URL for service configuration
        target_url = config_url
    else:
        target_url = f"{SERVICE_REGISTRY_URL}/services/{service_name}/config.json"

    try:
        req = urllib.request.Request(target_url)
        req.add_header('X-Lambda-Source', 'config-loader')
        with urllib.request.urlopen(req, timeout=5) as response:
            return response.read()
    except Exception as e:
        return json.dumps({'error': str(e)}).encode()

def load_plugin_script(plugin_url, integrity_hash=None):
    """Load and verify a plugin script with optional SRI verification."""
    try:
        req = urllib.request.Request(plugin_url)
        with urllib.request.urlopen(req, timeout=10) as response:
            content = response.read()

        if integrity_hash and not verify_integrity(content, integrity_hash):
            raise ValueError(f"Integrity check failed for {plugin_url}")

        return content
    except ValueError:
        raise
    except Exception as e:
        return None

def handler(event, context):
    """AWS Lambda handler for service configuration management."""
    action = event.get('action', 'get_config')

    if action == 'get_config':
        service_name = event.get('service_name', 'default')
        custom_url = event.get('config_url')  # SSRF vector: user-controlled URL

        config_data = fetch_service_config(service_name, config_url=custom_url)

        return {
            'statusCode': 200,
            'body': config_data.decode('utf-8', errors='replace')
        }

    elif action == 'load_plugin':
        plugin_url = event.get('plugin_url')
        integrity = event.get('integrity')  # SRI hash for plugin verification

        if not plugin_url:
            return {'statusCode': 400, 'body': 'plugin_url required'}

        try:
            content = load_plugin_script(plugin_url, integrity_hash=integrity)
            if content:
                return {
                    'statusCode': 200,
                    'body': content.decode('utf-8', errors='replace'),
                    'verified': integrity is not None
                }
        except ValueError as e:
            return {'statusCode': 403, 'body': str(e)}

        return {'statusCode': 502, 'body': 'Failed to load plugin'}

    elif action == 'health_check':
        # Internal health check - fetches metadata for diagnostics
        role_name = event.get('role_check', '')
        if role_name:
            url = f"{METADATA_ENDPOINT}{role_name}"
            try:
                with urllib.request.urlopen(url, timeout=2) as resp:
                    return {'statusCode': 200, 'body': resp.read().decode()}
            except:
                return {'statusCode': 200, 'body': 'healthy'}
        return {'statusCode': 200, 'body': 'healthy'}

    return {'statusCode': 400, 'body': 'Unknown action'}
